function kitFor(a,b){const gap=Math.hypot(...[1,3,5].map(i=>parseInt(a.color.slice(i,i+2),16)-parseInt(b.color.slice(i,i+2),16))),clash=gap<105;return {colors:[a.color,clash?b.away:b.color],secondary:[a.secondary,clash?b.color:b.secondary],keeper:['#e6ca64','#e6ad74']}}
function Shirt(props){return <PixelPlayer {...props}/>;}
