function Broadcast({title,subtitle}){const f=useCurrentFrame();return <AbsoluteFill style={{justifyContent:'center',alignItems:'center',fontFamily:'Space Grotesk, Microsoft YaHei, sans-serif',opacity:interpolate(f,[0,9,57,74],[0,1,1,0],{extrapolateRight:'clamp'})}}><div style={{position:'absolute',height:155,width:'110%',background:'#caff70',rotate:'-4deg',translate:`${interpolate(f,[0,12],[-1000,0],{extrapolateRight:'clamp'})}px 0px`}}/><div style={{zIndex:1,textAlign:'center',color:'#16220e',scale:interpolate(f,[5,17],[.8,1],{extrapolateLeft:'clamp',extrapolateRight:'clamp'})}}><div style={{fontSize:57,fontWeight:800,letterSpacing:3}}>{title}</div><div style={{fontSize:19,marginTop:9,letterSpacing:5}}>{subtitle}</div></div></AbsoluteFill>}


function contestRound(s){return s.week>=seasonRounds(s)?(s.cup?.results.filter(r=>r.home===s.teamId||r.away===s.teamId).length??0):0}
